import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.B3-dzFNu.js";const u=JSON.parse('{"title":"Redline","description":"AI code reviews for local Git changes and GitHub pull requests.","frontmatter":{"layout":"home","title":"Redline","description":"AI code reviews for local Git changes and GitHub pull requests.","hero":{"name":"Redline","text":"AI code reviews for your Git changes","tagline":"Review local work or automate pull request reviews with Pi or OpenCode and your choice of model. Read findings in the terminal and keep JSON and Markdown reports.","actions":[{"theme":"brand","text":"Get started","link":"/get-started/"},{"theme":"alt","text":"Set up GitHub Actions","link":"/get-started/github-actions"}]}},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1794060968000}'),n={name:"index.md"};function r(o,e,d,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[s('<h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><p><a href="/projects/redline/get-started/">Install Redline</a> and <a href="/projects/redline/get-started/configuration">connect Pi or OpenCode to a model</a>. Then run this from a Git repository with a commit and tracked changes. Model reviews send captured source to your selected provider and can incur charges.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --indexing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disabled</span></span></code></pre></div><p>Read findings and coverage in the terminal, then open <code>reviews/review.md</code> in the output directory printed by Redline. <code>--indexing disabled</code> keeps the first run independent of optional indexer setup.</p><h2 id="what-do-you-want-to-do" tabindex="-1">Next steps <a class="header-anchor" href="#what-do-you-want-to-do" aria-label="Permalink to &quot;Next steps {#what-do-you-want-to-do}&quot;">​</a></h2><ul><li><a href="/projects/redline/commands">Review staged changes, branches or commits</a>.</li><li><a href="/projects/redline/docker-workers">Run with Docker</a> using the bundled runtimes and harnesses.</li><li><a href="/projects/redline/results">Understand findings and saved reports</a>.</li><li><a href="/projects/redline/troubleshooting">Fix a setup or review failure</a>.</li></ul><h2 id="what-redline-does" tabindex="-1">What Redline does <a class="header-anchor" href="#what-redline-does" aria-label="Permalink to &quot;What Redline does&quot;">​</a></h2><p>Redline captures your change, reviews eligible files and checks findings against the diff. It does not execute the reviewed code or apply changes. Review suggestions before acting on them.</p><p>For planned integrations and upcoming work, see the <a href="/projects/redline/roadmap">roadmap</a>.</p><h2 id="the-shortest-safe-trial" tabindex="-1">No-key setup check <a class="header-anchor" href="#the-shortest-safe-trial" aria-label="Permalink to &quot;No-key setup check {#the-shortest-safe-trial}&quot;">​</a></h2><p>Prefer to check setup before connecting a model? After <a href="/projects/redline/get-started/">installation</a>, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">redline</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> review</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> echo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --indexing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disabled</span></span></code></pre></div><p><code>echo</code> makes no model request and always returns a clean answer. It checks the workflow, not code quality. The <a href="/projects/redline/get-started/first-review#_3-run-the-safe-review">first-review guide</a> includes a disposable example.</p>',13)])])}const k=t(n,[["render",r]]);export{u as __pageData,k as default};
